std::vector<Tetrahedron> result;
for (auto it = tri.triangulation.finite_cells_begin(); it != tri.triangulation.finite_cells_end(); ++it) {
    Tetrahedron tet;
    for (int i = 0; i < 4; ++i) {
        const auto& p = it->vertex(i)->point();
        tet[i] = cg3::Point3d(CGAL::to_double(p.x()), CGAL::to_double(p.y()), CGAL::to_double(p.z()));
    }
    result.push_back(tet);
}
return result;

